        {
            var value = new Validity();
            value.NotBefore = Asn1Kit.Modern.PKIX1Explicit2009.Time.Decode(reader);
            value.NotAfter = Asn1Kit.Modern.PKIX1Explicit2009.Time.Decode(reader);
